'use server';

import { splitRatioFromDatabase, splitRatioToDatabase } from '@/lib/displayTemplateSplitRatio';
import { getSupabaseServiceClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';

export type TemplateRow = {
  id: string;
  name: string;
  header_vh: number;
  score_vh: number;
  media_vh: number;
  ticker_vh: number;
  split_ratio: number;
  clock_style: string;
  clock_color: string;
  orientation: 'landscape' | 'portrait';
  font_scale: number;
  created_at?: string;
  updated_at?: string;
};

type RawTemplatePayload = {
  name?: string;
  header_vh?: number;
  score_vh?: number;
  media_vh?: number;
  ticker_vh?: number;
  split_ratio?: number;
  clock_style?: string;
  clock_color?: string;
  orientation?: string;
  font_scale?: number;
};

/** Solo primitivos serializables para el resultado de la Server Action (evita fallos de Flight). */
function toPlainTemplateRow(row: Record<string, unknown>): TemplateRow {
  const o = row.orientation;
  const orientation: 'landscape' | 'portrait' =
    o === 'portrait' ? 'portrait' : 'landscape';
  let font_scale = Number(row.font_scale);
  if (!Number.isFinite(font_scale) || font_scale <= 0) font_scale = 1;
  font_scale = Math.min(4, Math.max(0.5, font_scale));
  return {
    id: String(row.id ?? ''),
    name: String(row.name ?? ''),
    header_vh: Number(row.header_vh) || 0,
    score_vh: Number(row.score_vh) || 0,
    media_vh: Number(row.media_vh) || 0,
    ticker_vh: Number(row.ticker_vh) || 0,
    split_ratio: splitRatioFromDatabase(row.split_ratio),
    clock_style: String(row.clock_style ?? 'modern'),
    clock_color: String(row.clock_color ?? '#ccff00'),
    orientation,
    font_scale,
    created_at: row.created_at != null ? String(row.created_at) : undefined,
    updated_at: row.updated_at != null ? String(row.updated_at) : undefined,
  };
}

function normalizeTemplatePayload(input: RawTemplatePayload) {
  let h = Math.round(Math.max(0, Number(input.header_vh) || 10));
  let s = Math.round(Math.max(0, Number(input.score_vh) || 23));
  let m = Math.round(Math.max(0, Number(input.media_vh) || 59));
  const cap = Math.max(0, 100 - h - s);
  m = Math.min(m, cap);
  const t = 100 - h - s - m;
  const orientation =
    String(input.orientation ?? 'landscape').trim() === 'portrait'
      ? 'portrait'
      : 'landscape';
  let font_scale = Number(input.font_scale);
  if (!Number.isFinite(font_scale) || font_scale <= 0) font_scale = 1;
  font_scale = Math.min(4, Math.max(0.5, font_scale));

  return {
    name: (input.name || 'Sin Nombre').trim() || 'Sin Nombre',
    header_vh: h,
    score_vh: s,
    media_vh: m,
    ticker_vh: t,
    split_ratio: splitRatioToDatabase(input.split_ratio ?? 0.5),
    clock_style: input.clock_style || 'modern',
    clock_color: input.clock_color || '#ccff00',
    orientation,
    font_scale,
  };
}

export async function saveTemplateAction(
  id: string,
  payload: Record<string, unknown>,
): Promise<{ ok: true; data: TemplateRow } | { ok: false; error: string }> {
  const supabase = getSupabaseServiceClient();
  if (!supabase) {
    return {
      ok: false,
      error:
        'Servidor sin credenciales Supabase (service role). Configura SUPABASE_SERVICE_ROLE_KEY en el entorno de producción.',
    };
  }

  const isNew = id.startsWith('new-');
  const { id: _i, created_at: _c, updated_at: _u, ...rest } = payload;
  const data = normalizeTemplatePayload(rest as RawTemplatePayload);

  if (data.header_vh + data.score_vh + data.media_vh + data.ticker_vh !== 100) {
    return { ok: false, error: 'Los bloques VH deben sumar 100. Revisa cabecera, marcador y media.' };
  }

  try {
    if (isNew) {
      const { data: resData, error } = await supabase
        .from('display_templates')
        .insert([data])
        .select()
        .single();

      if (error) {
        return { ok: false, error: error.message || 'No se pudo crear el template.' };
      }
      revalidatePath('/admin/display/templates');
      return { ok: true, data: toPlainTemplateRow(resData as Record<string, unknown>) };
    }

    const { data: resData, error } = await supabase
      .from('display_templates')
      .update(data)
      .eq('id', id)
      .select()
      .single();

    if (error) {
      return { ok: false, error: error.message || 'No se pudo actualizar el template.' };
    }
    if (!resData) {
      return {
        ok: false,
        error: 'No se encontró el template en la base de datos. Recarga la página e inténtalo de nuevo.',
      };
    }
    revalidatePath('/admin/display/templates');
    return { ok: true, data: toPlainTemplateRow(resData as Record<string, unknown>) };
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : 'Error inesperado al guardar.';
    return { ok: false, error: msg };
  }
}

/** Solo `split_ratio` en BD (entero 0–100). Misma regla que el slider 0–1 del panel. */
export async function updateTemplateSplitRatioAction(
  templateId: string,
  newRatio: number,
): Promise<{ ok: true; stored: number } | { ok: false; error: string }> {
  const supabase = getSupabaseServiceClient();
  if (!supabase) {
    return {
      ok: false,
      error:
        'Servidor sin credenciales Supabase (service role). Configura SUPABASE_SERVICE_ROLE_KEY en el entorno de producción.',
    };
  }

  const id = String(templateId ?? '').trim();
  if (!id || id.startsWith('new-')) {
    return { ok: false, error: 'Guarda el template primero para poder persistir el split.' };
  }

  const normalizedRatio = splitRatioToDatabase(newRatio);

  try {
    const { data: resData, error } = await supabase
      .from('display_templates')
      .update({
        split_ratio: normalizedRatio,
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .select()
      .single();

    if (error) {
      return { ok: false, error: error.message || 'No se pudo actualizar split_ratio.' };
    }
    if (!resData) {
      return { ok: false, error: 'No se encontró el template.' };
    }
    revalidatePath('/admin/display/templates');
    return { ok: true, stored: normalizedRatio };
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : 'Error inesperado al guardar el split.';
    return { ok: false, error: msg };
  }
}

export async function applyTemplateToCanchaAction(
  venueName: string,
  canchaStorageId: string,
  templateId: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const supabase = getSupabaseServiceClient();
  if (!supabase) {
    return {
      ok: false,
      error:
        'Servidor sin credenciales Supabase (service role). Configura SUPABASE_SERVICE_ROLE_KEY en el entorno de producción.',
    };
  }

  const v = String(venueName ?? '').trim();
  const cid = String(canchaStorageId ?? '').trim();
  if (!cid) {
    return { ok: false, error: 'cancha_id inválido.' };
  }

  try {
    const iso = new Date().toISOString();
    const { data, error } = await supabase
      .from('canchas')
      .upsert(
        {
          venue_name: v,
          cancha_id: cid,
          current_template_id: templateId,
          updated_at: iso,
        },
        { onConflict: 'venue_name,cancha_id' },
      )
      .select('cancha_id');

    if (error) {
      return { ok: false, error: error.message || 'No se pudo aplicar el template a la cancha.' };
    }
    if (!data?.length) {
      return {
        ok: false,
        error: 'No se pudo confirmar la fila en canchas. Revisa la migración 040 (venue_name + cancha_id).',
      };
    }
    revalidatePath('/admin/display/templates');
    return { ok: true };
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : 'Error inesperado al aplicar.';
    return { ok: false, error: msg };
  }
}
